#include "KS/SRC/ks/FEMenu_shared.h"

enum EventType { SS_FE_ONX = 24 };

class SoundScriptManager {
public:
    static SoundScriptManager *instance;
    static inline SoundScriptManager *inst() { return instance; }
    void pause();
    void unpause();
    int playEvent(EventType type, entity *source = 0, float fade_in_time = 0.0f);
};

class PauseMenuSystem : public FEMenuSystem {
public:
    enum { GoalsMenu = 3, OptionsMenu = 4, ReplayMenu = 5, QuitConfirmMenu = 8 };
    bool draw;
    bool replay_mode;
    bool end_level;
    int pause_controller;
    int pause_player;
    void *map;
    TextString *player;
    int popupEvent;
    int navigationEvent;
    void Retry();
    void EndLevel();
};

class EndRunMenuClass : public FEMenu {
public:
    enum { Retry, BeachGoals, Options, Replay, Quit, ReturnToFE };
private:
    FEMenuEntry *replayEntry;
    FEMenuEntry *goalsEntry;
    FEMenuEntry *optionsEntry;
public:
    PauseMenuSystem *sys;
    FEMenuEntry *save;
    virtual void Select(int entry_index);
};

__asm__(".equ pause__18SoundScriptManager, 0x0031BF98");
__asm__(".equ unpause__18SoundScriptManager, 0x0031BFA8");
__asm__(".equ _18SoundScriptManager$instance, 0x0046B4A0");
__asm__(".equ playEvent__18SoundScriptManager9EventTypeP6entityf, 0x0031C380");
__asm__(".equ Retry__15PauseMenuSystem, 0x001B4920");
__asm__(".equ EndLevel__15PauseMenuSystem, 0x001B4980");

void EndRunMenuClass::Select(int entry_index)
{	
	SoundScriptManager::inst()->unpause();
	sys->navigationEvent=SoundScriptManager::inst()->playEvent(SS_FE_ONX);
	SoundScriptManager::inst()->pause();

	switch(entry_index)
	{
	case Retry:			sys->Retry(); break;
	case BeachGoals:	sys->MakeActive(PauseMenuSystem::GoalsMenu); break;
	case Options:		sys->MakeActive(PauseMenuSystem::OptionsMenu); break;
	case Replay:		sys->MakeActive(PauseMenuSystem::ReplayMenu); break;
	case Quit:			sys->EndLevel(); break;
	case ReturnToFE:	sys->MakeActive(PauseMenuSystem::QuitConfirmMenu); break;
	default: assert(0);
	}
}
